// zdx: sk83_na_zd functions transplanted into sk83_na_m.
//
// zdx_generated.cpp is the recompiled zd code itself (generated by
// sk83_na_zd/tools/zdx.py from tools/zdx_config.py -- regenerate, do not edit).
// The tool rewrote it to run here:
//   - calls go to m's matching functions, to other transplanted zd functions
//     (zdx_<zd address>) or to the host replacements in zdx_host.cpp;
//   - every zd global address goes through zdx::Map(), which returns the m
//     equivalent (m globals, m cvar objects) or a copy of zd's constant data
//     and zd-only state in the zdx pool (guest memory allocated on first use);
//   - struct offsets that moved between the builds are remapped.
//
// zd's DebugOverlay keeps its shapes in EA allocator pools; that part is
// replaced by a host queue (zdx_host.cpp) which replays every shape through
// the transplanted DebugShapeRenderer, the way zd's Shape::DrawAll does.

#pragma once

#include <cstddef>
#include <cstdint>

#include "generated/sk83_na_m_init.h"

namespace zdx {

using GuestFn = void (*)(PPCContext&, uint8_t*);

// ---- tables emitted by the generator
enum MapKind : uint32_t { kPool = 0, kM = 1 };
struct MapEntry {
  uint32_t zd_lo, zd_hi;
  MapKind kind;
  uint32_t value;  // kPool: offset in the pool; kM: m guest address of zd_lo
};
struct PoolFixup {
  uint32_t zd_addr;
  uint32_t value;  // poke value (zd address when relocated)
  bool reloc;      // value / current slot contents are a zd address: Map() it
  bool poke;       // write `value` (else keep the slot's snapshot contents)
};
// zd-only cvar: its object lives in the pool; zd's static initializer
// (transplanted) registers it with m's cvar system under the zd name.
struct ZdCvarInit {
  uint32_t zd_obj;
  const char* name;
  GuestFn init;
  uint32_t var_off;  // value-block pointer in the object: 32 bool, 40 int/float, 36 (zd 83D91738 kind)
  uint32_t reg;      // zd registration fn: 83D91558 bool, 83D915F0 int, 83D91680 float,
                     // 83D91738 enum (int), 83D91868 command (callback, no value)
};
struct VtableFixup {
  uint32_t zd_slot;   // vtable entry in the pool
  uint32_t m_addr;    // matched m function, or 0
  GuestFn host;       // transplanted function (gets a thunk address), or null
};
extern const VtableFixup kVtableFixups[];
struct VtMap {
  uint32_t m_vtable;
  uint32_t zd_vtable;
  const int16_t* slots;      // per zd slot: m slot, or -1 (m has no such method)
  const uint32_t* zd_fns;    // per zd slot: zd function address
  uint32_t count;
};
extern const VtMap kVtMaps[];
extern const size_t kVtMapCount;
struct Transplanted {
  uint32_t zd_addr;
  GuestFn fn;
};
extern const Transplanted kTransplanted[];

// A zd virtual call (slot offset zd_off of the vtable `vtable`) made by
// transplanted code: calls the m object's method in the matching m slot; for
// methods m dropped, the transplanted zd function if there is one.
void VirtualCall(PPCContext& ctx, uint8_t* base, uint32_t vtable, int32_t zd_off);
// bctrl through a function pointer; a null target is logged (with the zd
// function making the call) and skipped instead of hitting the fatal trap.
void IndirectCall(PPCContext& ctx, uint8_t* base, uint32_t zd_fn);
// Guest address for a transplanted zd function used as a value (sort
// comparator, callback): a dispatcher thunk, allocated once per function.
uint32_t FnThunk(GuestFn fn);
struct GameCvarName {
  const char* name;
  uint32_t obj;  // m cvar object, or (zd_only) the zd object (Map() it)
  bool zd_only;
  uint32_t var_off;  // value-block pointer in the object (see ZdCvarInit)
};
extern const GameCvarName kGameCvars[];  // every cvar m registers
extern const MapEntry kMapEntries[];
extern const size_t kMapEntryCount;
extern const PoolFixup kPoolFixups[];
extern const ZdCvarInit kZdCvarInits[];
extern const GuestFn kZdInits[];  // zd startup fragments (config INIT), null-terminated
extern const size_t kPoolSize;
extern const uint8_t kPoolInit[];

// zd guest address -> m guest address.
uint32_t Map(uint32_t zd_addr);
// Zeroed guest memory from the system heap (objects the host builds).
uint32_t AllocZeroed(uint8_t* base, uint32_t size, uint32_t align = 16);

// Extension block `id` of an m object (zeroed guest memory, created on first
// use): storage for fields zd's objects have and m's do not (zdx_config EXT).
extern const uint32_t kExtSizes[];
uint32_t Ext(uint32_t obj, uint32_t id);

// Once per simulation step, before zd code runs (from a guest callback):
// first call loads the pool and registers the zd-only cvars; then shape
// lifetimes (DebugOverlay::Update).
// Registers zd-only options / ThePrintChannelMan / the DebugOverlay (once).
void RegisterZdOnly(PPCContext& ctx, uint8_t* base);
void BeginFrame(PPCContext& ctx, uint8_t* base);
// zdx_graph_enable: Debug Graph channels to switch on (menus_debug.cpp).
void ApplyGraphChannels(PPCContext& ctx, uint8_t* base);
// zd's virtual debug draws into m's emptied vtable slots (vslots_debug.cpp; once).
void InstallVSlots(uint8_t* base);
// zdx_test_charmenu_item: fires a Character Debug Menu command (menus_debug.cpp).
void RunMenuTests(PPCContext& ctx, uint8_t* base);
// Flow message id of zd's 83 (enter the marquee viewer) in m (menus_debug.cpp).
int32_t MarqueeMessageId();
// The same, for zd code other than the menu (Juice BootUpMarqueeViewer): flags the request.
int32_t RequestMarqueeViewer();
// m's "marquee viewer finished" flow message (zd 83 + param 1; m's MVManager posts 81 + 1).
int32_t MarqueeDoneMessageId();
// m's create-a-skater stage around the marquee viewer (menus_debug.cpp).
void MarqueeStageBegin(PPCContext& ctx, uint8_t* base);
void MarqueeStageEnd(PPCContext& ctx, uint8_t* base);
// True once BeginFrame has built the pool and registered the zd-only cvars.
bool Ready();
// The pool is set up (initialized on demand): enough for zd code that reads
// no options (app-init singletons) before the first frame.
bool PoolReady(uint8_t* base);
// zdx_trace_blocks: log the first run of each debug block (generated hooks).
void TraceBlock(const char* name);

// Guest address of a cvar object by name (m's or zd-only), 0 if unknown.
uint32_t CvarObject(const char* name);
// Value-block pointer offset of that option's object (0 if unknown).
uint32_t CvarVarOffset(const char* name);
// True when the zd option object (zd address) is set: bool on, or a non-zero
// int/float/enum value. var_off/reg as in ZdCvarInit (zd registration fn).
bool OptionOn(uint8_t* base, uint32_t zd_obj, uint32_t var_off, uint32_t reg);

// Draws the queued shapes with the transplanted DebugShapeRenderer
// (Shape::DrawAll): the world-space ones, or the screen-space ones (Line2D,
// Rectangle, text). Call from a guest render callback with its context.
void DrawShapes(PPCContext& ctx, uint8_t* base, bool screen_space);

// Calls a transplanted / guest function from host code: runs `fn` on a copy
// of `ctx` whose stack pointer sits below the caller's frame.
// Runs transplanted code in place on the caller's context (an override that
// replaces an m function with zd's), with crash attribution.
void Run(PPCContext& ctx, uint8_t* base, GuestFn fn);

struct GuestCall {
  GuestCall(PPCContext& ctx, uint8_t* base, uint32_t scratch_bytes = 0x400);
  uint32_t scratch;  // 16-aligned guest scratch area of scratch_bytes
  PPCContext c;
  uint8_t* base;
  void operator()(GuestFn fn);
};

// DebugOverlay instance pointer the transplanted Draw* front-ends expect in r3.
uint32_t Overlay();
// Guest string "d:\logs": zd's PrintLogFile root (zdx_config PATCH on OpenLogFile).
uint32_t LogRoot();
// Sk8::GetGameVersionString with '/' -> '_' (r3): m's version string is
// "618274/618259/618097", which zd's metrics file paths would turn into
// folders that do not exist (juice_debug.cpp; zdx_config PATCH).
void GameVersionForPath(PPCContext& ctx, uint8_t* base);
// A game print (guest char*) for zd's output log file (logfile_debug.cpp).
void OnGamePrint(PPCContext& ctx, uint8_t* base, uint32_t text);
// zd's debug-strings panel (Debug::Manager), from the HUD text pass.
void DrawDebugStrings(PPCContext& ctx, uint8_t* base);

// Test helper (cacproto_debug.cpp): queue a viewer command for the CAC prototype.
bool TestPushProtoCommand(uint8_t* base, uint32_t cmd, float value);
}  // namespace zdx
